//mdl maker ui
function qc_gen_ui()
{
	var checkExist = ActiveSceneRoot.Properties("QC_Generator");

	if(checkExist)
	{
		DeleteObj(checkExist);
	} 

		//create ppg	
		var oPpg = ActiveSceneRoot.AddProperty("CustomProperty",false,"QC_Generator");
		var layout = oPpg.PPGLayout;
		
		//figure out what to populate the UI with
		scenename = ActiveProject.ActiveScene.Parameters("Name").Value;
		//figure out the qc name
		get_qcname(scenename);
		scenepath = ActiveProject.ActiveScene.Parameters("Filename").Value;
		//figure out the smd path
		get_smd_path(qc_name, scenepath);
		
		//add the UI variables
		oPpg.AddParameter3("scene_name", siString,qc_name);
		oPpg.AddParameter3("SMDfolder", siString,smd_path);
		
		//layout the UI
			layout.AddGroup("");
				layout.Additem ("scene_name", "QCname", siControlString);
				layout.AddItem ("SMDfolder", "SMD location:",siControlFolder);
				layout.AddButton("generateQC", "Launch QC Maker");
				layout.AddButton("compileMDL", "Compile MDL with existing QC");
				layout.AddButton("openMDL", "View MDL");
			layout.EndGroup();
			
		layout.Logic =  generateQC_OnClicked.toString()+
						compileMDL_OnClicked.toString()+
						openMDL_OnClicked.toString();
		layout.Language = "JScript";
	
		InspectObj(oPpg, null, null, 3);
}		

function get_smd_path(scenename,scenepath)
{
		//get the directory the scene is in
		scenename = ActiveProject.ActiveScene.Parameters("Name").Value;
		path_split = scenepath.split(scenename + ".scn");
		smdPath = path_split[0];
		//go up one directory tp get the smd path
		fso = new ActiveXObject("Scripting.FileSystemObject");
		f = fso.GetFolder(smdPath); 
		smd_path = f.ParentFolder;
		return (smd_path);			
}


//strip off _reference if there
function get_qcname(scenename)
{
	reference = "_reference";
	has_reference = scenename.match(/reference/);
	if (has_reference)
		{
			split_name = scenename.split(reference);	
			qc_name = split_name[0];
			return (qc_name);		
		}
	else
		{
			qc_name = scenename;
		return (scenename);	
	}	
		
}
//launch the QC Generator
function generateQC_OnClicked()
{
	folder = SMDfolder.value;
	qcname = scene_name.value;
	vproject = XSIUtils.Environment("VProject");
	tools_path = vproject.split("game");
	shell = new ActiveXObject("WScript.Shell");
	fso = new ActiveXObject("Scripting.FileSystemObject");
	qc_maker = (tools_path[0] + "game\\bin\\QCGenerator.exe -path " + folder + " -scene " + qcname);
	logmessage (qc_maker);
	shell.Run(qc_maker);
}


//open MDL
function openMDL_OnClicked()
{
	//change this to parse the QC and get model loaction
	mdl= ".mdl";
	mdlname = scene_name.value + mdl;
	shell = new ActiveXObject("WScript.Shell");
	smdPath = SMDfolder.value;
	//check if there is staging in the Vproject and look for mdl there
	vProject = XSIUtils.Environment("VProject");
	staging = "staging";
	inStaging = vProject.match(/staging/);
	mdlPath = smdPath.replace("content","game");
	slash = '/';
	if (inStaging)
	{
		stagingPath = vProject + slash + "models";
		mdlFile = stagingPath + slash + mdlname;
	}
	else
	{
		mdlFile = mdlPath + slash + mdlname;
	}
	//see if it exists first
	fso = new ActiveXObject("Scripting.FileSystemObject");
	exists = fso.FileExists(mdlFile)
	logmessage (mdlFile);


	if (exists)
	{
	shell.Run(mdlFile);
	}
	else
		{
		logmessage (mdlname + " MDL does not exist", siFatal)
		}
}	

//run studio mdl
function compileMDL_OnClicked()
{
	shell = new ActiveXObject("WScript.Shell");
	mdl= ".mdl";
	mdlname = scene_name.value + mdl;
	old_path = SMDfolder.value;
	mdl_path = old_path.replace("content","game");
	slash = '\\';
//studio MDL spits out a bunch of model names so we need to check all of them 
//and see if they need to be checked out
	mdl_filetype = new Array (".dx80.vtx", ".dx90.vtx", ".mdl", ".phy",".sw.vtx", ".vvd", ".xbox.vtx");
	files = new Array;
	for (i = 0; i < mdl_filetype.length; i++)
		{
			filename = mdl_path + slash + mdlname + mdl_filetype[i];
			fso = new ActiveXObject("Scripting.FileSystemObject");
			if (fso.FileExists(filename))
			{
			//		first see if the file needs to be checked out
			//		before exporting check if file is checked out
			file = fso.GetFile(filename);
			readonly =file.attributes & 1;
			if (readonly == 1)
				{
				//XSI won't allow me to write clean code so this big chunck of stuff is being inserted instead of trying
				//to call a function
					var checkExist = ActiveSceneRoot.Properties("Checkout");
					if(checkExist)
					{
					logmessage ("Deleting Checkout Property");
					DeleteObj(checkExist);
					} 
				//create ppg
				var oPpg = ActiveSceneRoot.AddProperty("CustomProperty",false,"Checkout");
				var chklayout = oPpg.PPGlayout;
				//store filename here
				oPpg.AddParameter3("file_name", siString, filename);

				chklayout.addGroup();
					chklayout.addRow();
							chklayout.Additem ("file_name", "File:", siControlString);
					chklayout.endRow();
	
				chklayout.endGroup();

				chklayout.Language = "JScript";
				
				checkoutfile = InspectObj(oPpg, "", "Check Out File", 4,false);
				if (!checkoutfile)
				{	
					vstcheckoutfile(filename);
		
				}		
				else
				{
					logmessage ("user cancelled");
				}	
			}
			}
		}
	vproject = XSIUtils.Environment("VProject");
	studiomdl_path = vproject.split("game");
	qc = ".qc";
	qc_name =  scene_name.value + qc;
	qc_file = old_path + "/" + qc_name;
	shell = new ActiveXObject("WScript.Shell");
	fso = new ActiveXObject("Scripting.FileSystemObject");
	exists = fso.FileExists(qc_file)
	if (!exists)
	{
		logmessage ("Can't find the QC file: " + qc_file, siFatal);
		return;
	}
	path = SMDfolder.value;
	slash = '/';
	qc_file = path + slash + qc_name;
	studiomdl = (studiomdl_path[0] + "game/bin/studiomdl.bat " + qc_file);
	logmessage (studiomdl);
	shell.Run(studiomdl);
}
